-- SOLO SELECT/SHOW. Seleccionar y verificar manualmente la base destino. Ejecutar por separado.
-- Metadata puede no ser visible sin permisos; ausencia no es certificacion.
-- VARIANTE CON ESQUEMA EXPLÍCITO de `10-preflight-fondos.sql` (SOLO LECTURA): mismas validaciones, pero TODAS las consultas a information_schema filtran por `@esquema` y NINGUNA usa DATABASE().
-- Sirve cuando el cliente (p. ej. phpMyAdmin) ejecuta con DATABASE() = information_schema u otro esquema: la versión original daría falsos errores de columnas/índices faltantes.
-- Editar el nombre EXACTO de la base de la aplicación en la línea SET y ejecutar el archivo completo. Fail-closed: un esquema NULL/vacío/inexistente/del sistema o sin `flota_cb2_consumos` produce filas de problema.
SET @esquema = 'u611730801_Plataforma';   -- ← base de la aplicación
-- CERO filas esperado: cualquier fila indica esquema NO válido para este preflight (DETENER).
SELECT 'ESQUEMA_NO_FIJADO_NO_EXISTE_O_NO_PERMITIDO' problema FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=@esquema AND @esquema IS NOT NULL AND @esquema<>'' AND SCHEMA_NAME NOT IN ('information_schema','mysql','performance_schema','sys')) UNION ALL SELECT 'BASE_CB2_AUSENTE_EN_EL_ESQUEMA (flota_cb2_consumos no existe)' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@esquema AND TABLE_NAME='flota_cb2_consumos');
SELECT @esquema esquema_analizado,IF(EXISTS(SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=@esquema AND @esquema IS NOT NULL AND @esquema<>'' AND SCHEMA_NAME NOT IN ('information_schema','mysql','performance_schema','sys')),'ESQUEMA_VALIDO','ESQUEMA_INVALIDO') estado_esquema,VERSION() version,@@foreign_key_checks fk,@@check_constraint_checks ck,@@sql_mode sql_mode;
SHOW GRANTS;
-- DETENER si la base/version no corresponde o FK/CHECK no son 1.
-- CERO filas esperado: cualquier tabla nueva visible exige detener por instalacion previa/parcial.
SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=@esquema AND TABLE_NAME IN('flota_cb2_fondos_vinculos') UNION ALL SELECT 'ESQUEMA_INVALIDO' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=@esquema AND @esquema IS NOT NULL AND @esquema<>'' AND SCHEMA_NAME NOT IN ('information_schema','mysql','performance_schema','sys'));
WITH requeridas AS (SELECT 'usuarios' tabla,'id' columna UNION ALL SELECT 'flota_cb2_consumos','empresa_id' UNION ALL SELECT 'flota_cb2_consumos','proveedor_id' UNION ALL SELECT 'flota_cb2_consumos','id' UNION ALL SELECT 'tms_solicitud_fondo_lineas','empresa_id' UNION ALL SELECT 'tms_solicitud_fondo_lineas','id') SELECT r.*,c.COLUMN_TYPE,c.IS_NULLABLE,t.ENGINE FROM requeridas r LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=@esquema AND c.TABLE_NAME=r.tabla AND c.COLUMN_NAME=r.columna LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE c.COLUMN_NAME IS NULL OR c.DATA_TYPE<>'int' OR c.COLUMN_TYPE LIKE '%unsigned%' OR c.IS_NULLABLE<>'NO' OR COALESCE(t.ENGINE,'')<>'InnoDB';
WITH requeridos AS (SELECT 'flota_cb2_consumos' tabla,'uq_cb2c_ambito' indice,'empresa_id,proveedor_id,id' columnas,0 no_unico UNION ALL SELECT 'usuarios','PRIMARY','id',0 UNION ALL SELECT 'tms_solicitud_fondo_lineas','uq_fondolin_c2a_empresa_id','empresa_id,id',0) SELECT r.*,'INDICE_INCOMPATIBLE_O_FALTANTE' problema FROM requeridos r WHERE NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA=@esquema AND s.TABLE_NAME=r.tabla AND s.INDEX_NAME=r.indice GROUP BY s.INDEX_NAME HAVING MAX(s.NON_UNIQUE)=r.no_unico AND MIN(s.NON_UNIQUE)=r.no_unico AND GROUP_CONCAT(s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX)=r.columnas AND SUM(s.SUB_PART IS NOT NULL)=0 AND MIN(s.INDEX_TYPE)='BTREE');
-- CERO esperado: nombres FK ya ocupados en el esquema.
SELECT TABLE_NAME,CONSTRAINT_NAME FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=@esquema AND CONSTRAINT_NAME IN('fk_cb2fv_consumo','fk_cb2fv_linea','fk_cb2fv_actor') UNION ALL SELECT 'ESQUEMA_INVALIDO',NULL FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=@esquema AND @esquema IS NOT NULL AND @esquema<>'' AND SCHEMA_NAME NOT IN ('information_schema','mysql','performance_schema','sys'));
